<template>
  <section class="build-panel" data-doc="manual/build-automation">
    <header class="build-header">
      <div><strong>{{ t('buildPanel') }}</strong><p>{{ t('shippingWorkspaceHint') }}</p></div>
      <nav role="tablist"><button v-for="tab in tabs" :key="tab.id" :class="{ active: activeTab === tab.id }" @click="activeTab = tab.id">{{ t(tab.label) }}</button></nav>
    </header>
    <div class="build-body">
      <main class="build-workspace">
        <section v-if="activeTab === 'overview'" class="tab-page overview-page">
          <div class="section-heading"><div><strong>{{ t('buildOverview') }}</strong><p>{{ targetNote }}</p></div><span :class="['target-badge', currentSupport.tier]">{{ supportTier }} · {{ targetLabel }} · {{ buildSettings.architecture }}</span></div>
          <div class="field-grid">
            <label><span>{{ t('buildPreset') }}</span><select :value="buildSettings.presetName" @change="applyBuildPreset(($event.target as HTMLSelectElement).value)"><option value="custom">{{ t('custom') }}</option><option v-for="preset in BUILTIN_BUILD_PRESETS" :key="preset.id" :value="preset.id">{{ preset.name }}</option></select></label>
            <label><span>{{ t('buildGameName') }}</span><input v-model="buildSettings.gameName" maxlength="80"></label>
            <label><span>{{ t('buildTarget') }}</span><select v-model="buildSettings.target"><option v-for="platform in selectablePlatforms" :key="platform.id" :value="platform.id">{{ platform.label }} · {{ platformTierLabel(platform.tier) }}</option></select></label>
            <label><span>{{ t('architecture') }}</span><select v-model="buildSettings.architecture"><option value="x86_64">x86_64</option><option value="aarch64">aarch64</option></select></label>
            <label><span>{{ t('buildProfile') }}</span><select :value="buildSettings.profile" @change="setBuildProfile(($event.target as HTMLSelectElement).value as BuildProfile)"><option value="debug">{{ t('debugProfile') }}</option><option value="release">{{ t('releaseProfile') }}</option></select></label>
            <label><span>{{ t('runtimeMode') }}</span><select v-model="buildSettings.runtimeMode"><option value="game">{{ t('gameRuntime') }}</option><option value="headless-server">{{ t('headlessServer') }}</option></select></label>
            <label class="wide"><span>{{ t('outputDirectory') }}</span><input v-model="buildSettings.outputDirectory" :placeholder="t('defaultOutput')"></label>
            <label class="check"><input v-model="buildSettings.packageIntoExecutable" type="checkbox" :disabled="!singleFileAvailable"><span>{{ t('packageExecutable') }}</span></label>
          </div>
          <section class="artifact-card" aria-live="polite">
            <span class="artifact-icon" aria-hidden="true">↗</span>
            <div><strong>{{ t(artifactTitle) }}</strong><p>{{ t(artifactDescription) }}</p></div>
            <code>{{ artifactExtension }}</code>
          </section>
          <section class="scenes-card">
            <header><strong>{{ t('sceneOrder') }}</strong><span>{{ t('startupScene') }}</span></header>
            <article v-for="(uuid, index) in buildSettings.sceneOrder" :key="uuid"><span class="index">{{ index + 1 }}</span><strong>{{ sceneName(uuid) }}</strong><label><input v-model="buildSettings.startupSceneUuid" type="radio" :value="uuid"><span>{{ t('startupScene') }}</span></label><button :disabled="index === 0" :title="t('moveUp')" @click="move(index, -1)">↑</button><button :disabled="index === buildSettings.sceneOrder.length - 1" :title="t('moveDown')" @click="move(index, 1)">↓</button></article>
          </section>
        </section>

        <section v-else-if="activeTab === 'platform'" class="tab-page">
          <div class="section-heading"><div><strong>{{ t('platformPreset') }}</strong><p>{{ t('platformPresetHint') }}</p></div><button @click="applyPreset">{{ t('applyRecommendedPreset') }}</button></div>
          <div class="field-grid">
            <label><span>{{ t('applicationIdentifier') }}</span><input v-model="buildSettings.platform.identifier" maxlength="160"></label>
            <label><span>{{ t('applicationVersion') }}</span><input v-model="buildSettings.platform.version" maxlength="40"></label>
            <label><span>{{ t('orientation') }}</span><select v-model="buildSettings.platform.orientation"><option value="auto">{{ t('automatic') }}</option><option value="landscape">{{ t('landscape') }}</option><option value="portrait">{{ t('portrait') }}</option></select></label>
            <label><span>{{ t('iconAsset') }}</span><input v-model="iconAsset" placeholder="asset://GUID"></label>
            <label><span>{{ t('splashAsset') }}</span><input v-model="splashAsset" placeholder="asset://GUID"></label>
            <label><span>{{ t('platformManifest') }}</span><input v-model="manifestAsset" placeholder="asset://GUID"></label>
            <label class="wide"><span>{{ t('permissions') }}</span><input v-model="permissionText" :placeholder="t('permissionsPlaceholder')"></label>
            <label><span>{{ t('signingMode') }}</span><select v-model="buildSettings.platform.signingMode"><option value="none">{{ t('unsigned') }}</option><option value="manual">{{ t('manualSigning') }}</option></select></label>
            <label v-if="buildSettings.platform.signingMode === 'manual'"><span>{{ t('signingIdentity') }}</span><input v-model="buildSettings.platform.signingIdentity"></label>
            <label v-if="buildSettings.target === 'macos'"><span>{{ t('notarizationProfile') }}</span><input v-model="buildSettings.platform.notarizationProfile"></label>
          </div>
          <div class="guidance"><strong>{{ t('platformGuidance') }}</strong><p>{{ platformGuidance }}</p><p v-if="buildSettings.target === 'android'">{{ exportCapabilities.androidReason }}</p></div>
        </section>

        <section v-else-if="activeTab === 'delivery'" class="tab-page">
          <div class="section-heading"><div><strong>{{ t('deliveryPipeline') }}</strong><p>{{ t('deliveryPipelineHint') }}</p></div></div>
          <div class="option-grid">
            <label><input v-model="buildSettings.delivery.deterministic" type="checkbox"><span><strong>{{ t('reproducibleBuild') }}</strong><small>{{ t('reproducibleBuildHint') }}</small></span></label>
            <label><input v-model="buildSettings.delivery.incremental" type="checkbox"><span><strong>{{ t('incrementalBuild') }}</strong><small>{{ t('incrementalBuildHint') }}</small></span></label>
            <label><input v-model="buildSettings.delivery.patchManifest" type="checkbox"><span><strong>{{ t('patchManifest') }}</strong><small>{{ t('patchManifestHint') }}</small></span></label>
            <label><input v-model="buildSettings.delivery.contentCache" type="checkbox"><span><strong>{{ t('contentCache') }}</strong><small>{{ t('reproducibleBuildHint') }}</small></span></label>
            <label><input v-model="buildSettings.delivery.deltaBuilds" type="checkbox"><span><strong>{{ t('deltaBuilds') }}</strong><small>{{ t('patchManifestHint') }}</small></span></label>
            <label><input v-model="buildSettings.delivery.structuredLogs" type="checkbox"><span><strong>{{ t('structuredLogs') }}</strong><small>{{ t('structuredLogsHint') }}</small></span></label>
            <label><input v-model="buildSettings.delivery.crashReports" type="checkbox"><span><strong>{{ t('crashCapture') }}</strong><small>{{ t('crashCaptureHint') }}</small></span></label>
            <label><input v-model="buildSettings.delivery.stripUnusedAssets" type="checkbox"><span><strong>{{ t('stripUnusedAssets') }}</strong><small>{{ t('stripUnusedAssetsHint') }}</small></span></label>
            <label><input v-model="buildSettings.delivery.sizeReport" type="checkbox"><span><strong>{{ t('buildSizeReport') }}</strong><small>{{ t('buildSizeReportHint') }}</small></span></label>
            <label><input v-model="buildSettings.delivery.dependencyReport" type="checkbox"><span><strong>{{ t('dependencyReport') }}</strong><small>{{ t('dependencyReportHint') }}</small></span></label>
            <label><input v-model="buildSettings.delivery.debugSymbols" type="checkbox"><span><strong>{{ t('debugSymbols') }}</strong><small>{{ t('debugSymbolsHint') }}</small></span></label>
            <label><input v-model="buildSettings.delivery.crashSymbols" type="checkbox"><span><strong>{{ t('crashSymbols') }}</strong><small>{{ t('crashSymbolsHint') }}</small></span></label>
          </div>
          <div class="field-grid delivery-fields"><label><span>{{ t('releaseChannel') }}</span><select v-model="buildSettings.delivery.releaseChannel"><option value="stable">{{ t('stable') }}</option><option value="beta">{{ t('beta') }}</option><option value="development">{{ t('development') }}</option></select></label><label><span>{{ t('exportTemplate') }}</span><select v-model="buildSettings.delivery.exportTemplate"><option v-for="template in exportTemplateState.templates" :key="template.id" :value="template.id">{{ template.name }} · {{ template.installed ? t('installed') : t('notInstalled') }}</option></select></label><label><span>{{ t('cacheMode') }}</span><select v-model="buildSettings.delivery.cacheMode"><option value="clean">{{ t('cleanBuild') }}</option><option value="incremental">{{ t('incrementalBuild') }}</option><option value="validate">{{ t('validateCache') }}</option></select></label><label><span>{{ t('compression') }}</span><select v-model="buildSettings.delivery.compression"><option value="store">{{ t('storeCompression') }}</option><option value="balanced">{{ t('balancedCompression') }}</option><option value="maximum">{{ t('maximumCompression') }}</option></select></label><label><span>{{ t('includeRules') }}</span><input v-model="includeRules" placeholder="Assets/**"></label><label><span>{{ t('excludeRules') }}</span><input v-model="excludeRules" placeholder="**/*.psd, .nova/**"></label><label><span>{{ t('deploymentMode') }}</span><select v-model="buildSettings.delivery.deploymentMode"><option value="local">{{ t('localOnly') }}</option><option value="remote-hook">{{ t('explicitRemoteHook') }}</option></select></label><label v-if="buildSettings.delivery.deploymentMode === 'remote-hook'"><span>{{ t('deploymentDestination') }}</span><input v-model="buildSettings.delivery.deploymentDestination" placeholder="https://"></label><label><span>{{ t('signingHook') }}</span><input v-model="buildSettings.delivery.signingHook" :placeholder="t('externalExplicitHook')"></label><label><span>{{ t('notarizationHook') }}</span><input v-model="buildSettings.delivery.notarizationHook" :placeholder="t('externalExplicitHook')"></label></div>
          <div class="option-grid release-options"><label><input v-model="buildSettings.delivery.provenance" type="checkbox"><span><strong>{{ t('buildProvenance') }}</strong><small>{{ t('buildProvenanceHint') }}</small></span></label><label><input v-model="buildSettings.delivery.sbom" type="checkbox"><span><strong>{{ t('softwareBillOfMaterials') }}</strong><small>CycloneDX 1.5</small></span></label><label><input v-model="buildSettings.delivery.webHeaders" type="checkbox"><span><strong>{{ t('webDeploymentHeaders') }}</strong><small>{{ t('webDeploymentHeadersHint') }}</small></span></label><label><input v-model="buildSettings.delivery.cleanMachineJob" type="checkbox"><span><strong>{{ t('cleanMachineJob') }}</strong><small>{{ t('cleanMachineJobHint') }}</small></span></label><label v-if="buildSettings.delivery.deploymentMode === 'remote-hook'"><input v-model="buildSettings.delivery.deploymentPermissionGranted" type="checkbox"><span><strong>{{ t('grantDeploymentPermission') }}</strong><small>{{ t('neverDeploysAutomatically') }}</small></span></label></div>
          <section class="privacy-card">
            <header><div><strong>{{ t('optInTelemetry') }}</strong><small>{{ t('telemetryDisabledDefault') }}</small></div><input v-model="buildSettings.delivery.telemetryEnabled" type="checkbox"></header>
            <div v-if="buildSettings.delivery.telemetryEnabled" class="field-grid"><label><span>{{ t('telemetryEndpoint') }}</span><input v-model="buildSettings.delivery.telemetryEndpoint" placeholder="https://"></label><label><span>{{ t('privacyPolicy') }}</span><input v-model="buildSettings.delivery.privacyPolicyUrl" placeholder="https://"></label></div>
            <ul><li v-for="line in privacySummary" :key="line">{{ line }}</li></ul>
          </section>
          <section class="cli-card"><strong>{{ t('commandLineExport') }}</strong><code>pnpm nova export --project project.nova --target {{ buildSettings.target }} --profile {{ buildSettings.profile }} --cache {{ buildSettings.delivery.cacheMode }} --jsonl</code><p>{{ t('commandLineExportHint') }}</p></section>
        </section>

        <section v-else-if="activeTab === 'diagnostics'" class="tab-page diagnostics-page">
          <div class="section-heading"><div><strong>{{ t('buildDiagnostics') }}</strong><p>{{ t('buildDiagnosticsHint') }}</p></div></div>
          <section class="support-matrix"><article v-for="platform in PLATFORM_SUPPORT_MATRIX" :key="platform.id"><span :class="['support-badge', platform.tier]">{{ platformTierLabel(platform.tier) }}</span><div><strong>{{ platform.label }} · {{ platform.architectures.join(', ') }} · {{ platform.availability }}</strong><p>{{ platform.reason }}</p><small>{{ platform.minimumSystem }} · {{ platform.evidence }}</small></div></article></section>
          <section class="freeze-card"><header><div><strong>{{ t('releaseCandidateFreeze') }}</strong><small>{{ RELEASE_CANDIDATE_FREEZE.release }} · {{ RELEASE_CANDIDATE_FREEZE.minimumDays }} {{ t('days') }}</small></div><span>{{ RELEASE_CANDIDATE_FREEZE.active ? t('active') : t('inactive') }}</span></header><p>{{ RELEASE_CANDIDATE_FREEZE.policy }}</p><div class="chips"><span v-for="contract in RELEASE_CANDIDATE_FREEZE.frozenContracts" :key="contract">{{ contract }}</span></div></section>
          <section class="pipeline-card"><header><strong>{{ t('releasePipeline') }}</strong><span>{{ NOVA_RELEASE_PIPELINE.length }}</span></header><article v-for="stage in NOVA_RELEASE_PIPELINE" :key="stage.id"><span>{{ stage.required ? '✓' : '○' }}</span><div><strong>{{ stage.label }}</strong><code>{{ stage.command }}</code></div><small>{{ stage.mutation }}</small></article></section>
          <section class="history-card"><header><strong>{{ t('buildHistory') }}</strong><span>{{ buildHistory.length }}</span></header><article v-for="entry in buildHistory" :key="entry.id"><span :class="entry.status">{{ entry.status }}</span><div><strong>{{ entry.target }} · {{ entry.profile }} · {{ entry.buildId.slice(0, 12) }}</strong><small>{{ new Date(entry.finishedAt).toLocaleString() }} · {{ entry.outputPath }}</small><small v-if="entry.cacheKey">{{ t('cacheKey') }} {{ entry.cacheKey }} · {{ Math.round(entry.durationMs ?? 0) }} ms · {{ entry.evidenceStatus }}</small></div><b>{{ Math.round(entry.sizeBytes / 1024) }} KB</b></article><p v-if="!buildHistory.length">{{ t('noBuildHistory') }}</p></section>
          <section v-if="releaseEngineeringState.lastComparison" class="comparison-card"><strong>{{ t('deterministicComparison') }}</strong><dl><div><dt>{{ t('inputs') }}</dt><dd>{{ releaseEngineeringState.lastComparison.inputMatch ? t('match') : t('different') }}</dd></div><div><dt>{{ t('outputs') }}</dt><dd>{{ releaseEngineeringState.lastComparison.outputMatch ? t('match') : t('different') }}</dd></div><div><dt>{{ t('changedFiles') }}</dt><dd>{{ releaseEngineeringState.lastComparison.changed.length }}</dd></div></dl></section>
        </section>

        <TeamWorkflowPanel v-else />
      </main>

      <aside class="build-actions">
        <header><strong>{{ progressTitle }}</strong><span :class="['readiness-badge', readinessState]">{{ readinessLabel }}</span></header>
        <p>{{ buildProgress.message || t('buildIdle') }}</p><div class="progress"><i :style="{ width: `${buildProgress.percent}%` }"></i></div>
        <code v-if="buildProgress.outputPath">{{ buildProgress.outputPath }}</code>
        <section class="validation-list"><article v-for="issue in issues" :key="issue.code" :class="issue.severity"><strong>{{ issue.severity }}</strong><span>{{ issue.message }}</span><button :aria-label="`${t('documentation')}: ${issue.code}`" @click="openBundledManual(issue.helpTarget)">?</button></article><p v-if="!issues.length">{{ t('buildValidationPassed') }}</p></section>
        <dl><div><dt>{{ t('buildLocales') }}</dt><dd>{{ localizationSettings.buildLocales.length }}</dd></div><div><dt>{{ t('localizationIssues') }}</dt><dd>{{ localizationAudit.length }}</dd></div><div><dt>{{ t('accessibilityIssues') }}</dt><dd>{{ accessibilityAudit.length }}</dd></div><div><dt>{{ t('buildCacheHits') }}</dt><dd>{{ buildProgress.cacheHits }}</dd></div><div><dt>{{ t('changedFiles') }}</dt><dd>{{ buildProgress.changedFiles }}</dd></div><div><dt>{{ t('host') }}</dt><dd>{{ exportCapabilities.host }}</dd></div></dl>
        <section v-if="pluginBuildContributions.length" class="plugin-build-steps"><strong>{{ t('extensionBuildSteps') }}</strong><span v-for="item in pluginBuildContributions" :key="`${item.pluginId}:${item.kind}:${item.id}`">{{ item.label }} <small>{{ item.pluginName }}</small></span></section>
        <button class="primary" :disabled="busy || hasErrors" :title="buildDisabledReason" @click="runBuild(false)">{{ t('build') }}</button><button :disabled="busy || hasErrors || buildSettings.target === 'web' || buildSettings.target === 'android'" :title="runDisabledReason" @click="runBuild(true)">{{ t('buildAndRun') }}</button>
        <p v-if="buildSettings.runtimeMode === 'headless-server'" class="note">{{ t('headlessServerHint') }}</p>
      </aside>
    </div>
  </section>
</template>

<script setup lang="ts">
import { computed, onMounted, ref, watch } from 'vue'
import { t } from '../i18n'
import { BUILTIN_BUILD_PRESETS, applyBuildPreset, buildHistory, buildProgress, buildSettings, detectExportCapabilities, exportCapabilities, persistBuildLocalSettings, setBuildProfile, synchronizeBuildScenes, validateBuildSettings, type BuildProfile } from '../runtime/buildSettings'
import { PLATFORM_SUPPORT_MATRIX, platformSupport, platformTierLabel, selectableBuildPlatforms } from '../runtime/platformSupport'
import { buildGame, failBuild } from '../runtime/gameExporter'
import { physicsState, sceneManager } from '../store/physics'
import { telemetryPrivacySummary } from '../runtime/shipping'
import TeamWorkflowPanel from './TeamWorkflowPanel.vue'
import { completeTask, failTask, startTask, updateTask } from '../runtime/editorFeedback'
import { assetState, readTextAsset } from '../assets/AssetDatabase'
import { extractLocalizationKeys, localizationDiagnostics, localizationSettings, readLocalizationTable } from '../runtime/localization'
import { runtimeAccessibilitySettings } from '../runtime/presentation'
import { auditUiAccessibility } from '../runtime/uiAccessibility'
import { validateProductionRuntime } from '../runtime/productionValidation'
import { editorState } from '../store/editor'
import { NOVA_RELEASE_PIPELINE, RELEASE_CANDIDATE_FREEZE, releaseEngineeringState } from '../runtime/releaseEngineering'
import { openBundledManual } from '../runtime/openManual'
import { compileGraphSource } from '../visual/graphCompiler'
import { exportTemplateState } from '../runtime/exportTemplates'
import { pluginRuntime, pluginState } from '../runtime/plugins'

type BuildTab = 'overview' | 'platform' | 'delivery' | 'diagnostics' | 'team'
const tabs: Array<{ id: BuildTab; label: string }> = [{ id: 'overview', label: 'buildOverview' }, { id: 'platform', label: 'platformPreset' }, { id: 'delivery', label: 'deliveryPipeline' }, { id: 'diagnostics', label: 'buildDiagnostics' }, { id: 'team', label: 'teamWorkflow' }]
const activeTab = ref<BuildTab>('overview')
const pluginBuildContributions = computed(() => pluginState.contributions.filter(item => item.kind === 'buildHooks' || item.kind === 'buildSteps'))
const busy = computed(() => ['validating', 'packing', 'exporting'].includes(buildProgress.phase))
const localizationKeys = computed(() => extractLocalizationKeys(physicsState.world.entities, assetState.records.filter(asset => asset.assetType === 'script').map(asset => ({ path: asset.path, source: readTextAsset(asset.uuid) ?? '' }))))
const localizationTables = computed(() => assetState.records.flatMap(asset => { if (asset.assetType !== 'localization') return []; const table = readLocalizationTable(asset.uuid); return table ? [table] : [] }))
const localizationAudit = computed(() => localizationDiagnostics(localizationKeys.value, localizationTables.value).filter(issue => localizationSettings.buildLocales.some(locale => locale.toLowerCase() === issue.locale.toLowerCase())))
const accessibilityAudit = computed(() => auditUiAccessibility(physicsState.world.entities, runtimeAccessibilitySettings.minimumTargetSize))
const presentationBuildIssues = computed(() => [...localizationAudit.value.map(issue => ({ code: `build-${issue.code}-${issue.locale}-${issue.key}`, severity: issue.severity === 'error' ? 'error' as const : 'warning' as const, message: `${issue.locale} · ${issue.key}: ${issue.message}`, helpTarget: 'localization-accessibility' })), ...accessibilityAudit.value.map(issue => ({ code: `build-${issue.code}-${issue.entityUuid}`, severity: issue.severity === 'error' ? 'error' as const : 'warning' as const, message: `${issue.entityName}: ${issue.message}`, helpTarget: 'localization-accessibility' }))])
const productionBuildIssues = computed(() => validateProductionRuntime(assetState, editorState.rendererStats, physicsState.audioSettings).map(issue => ({ code: `production-${issue.code}`, severity: issue.severity, message: `${issue.message} ${issue.fix}`, helpTarget: 'troubleshooting' })))
const graphBuildIssues = computed(() => assetState.records.filter(asset => asset.assetType === 'visualScript').flatMap(asset => { try { return compileGraphSource(readTextAsset(asset.uuid) ?? '').diagnostics.filter(item => item.severity === 'error').map((item,index) => ({ code: `graph-${asset.uuid}-${index}`, severity: 'error' as const, message: `${asset.path}: ${item.message}`, helpTarget: 'project-health' })) } catch (error) { return [{ code: `graph-${asset.uuid}-parse`, severity: 'error' as const, message: `${asset.path}: ${error instanceof Error ? error.message : String(error)}`, helpTarget: 'project-health' }] } }))
const issues = computed(() => [...validateBuildSettings(buildSettings), ...graphBuildIssues.value, ...presentationBuildIssues.value, ...productionBuildIssues.value].slice(0, 256))
const hasErrors = computed(() => issues.value.some(issue => issue.severity === 'error'))
const hasWarnings = computed(() => issues.value.some(issue => issue.severity === 'warning'))
const readinessState = computed(() => busy.value ? 'in-progress' : hasErrors.value ? 'blocked' : hasWarnings.value ? 'ready-warnings' : 'ready')
const readinessLabel = computed(() => t(readinessState.value === 'in-progress' ? 'readinessInProgress' : readinessState.value === 'blocked' ? 'readinessBlocked' : readinessState.value === 'ready-warnings' ? 'readinessWarnings' : 'readinessReady'))
const buildDisabledReason = computed(() => busy.value ? t('buildAlreadyRunning') : hasErrors.value ? t('resolveBuildErrors') : '')
const runDisabledReason = computed(() => buildDisabledReason.value || (buildSettings.target === 'web' || buildSettings.target === 'android' ? t('buildRunUnsupportedTarget') : ''))
const singleFileAvailable = computed(() => buildSettings.target === 'windows' || buildSettings.target === 'linux')
const artifactTitle = computed(() => buildSettings.target === 'web' ? 'webFolderArtifact' : buildSettings.packageIntoExecutable && singleFileAvailable.value ? 'portableApplicationArtifact' : 'playerAndPackArtifact')
const artifactDescription = computed(() => buildSettings.target === 'web' ? 'webFolderArtifactHint' : buildSettings.packageIntoExecutable && singleFileAvailable.value ? 'portableApplicationArtifactHint' : 'playerAndPackArtifactHint')
const artifactExtension = computed(() => buildSettings.target === 'web' ? 'index.html + game.nova-pak' : buildSettings.target === 'windows' ? (buildSettings.packageIntoExecutable ? '.exe' : '.exe + .nova-pak') : buildSettings.target === 'macos' ? '.app + .nova-pak' : buildSettings.target === 'linux' ? (buildSettings.packageIntoExecutable ? 'executable' : 'executable + .nova-pak') : '.apk')
const selectablePlatforms = selectableBuildPlatforms()
const currentSupport = computed(() => platformSupport(buildSettings.target))
const supportTier = computed(() => platformTierLabel(currentSupport.value.tier))
const targetLabel = computed(() => buildSettings.target === 'windows' ? t('windows') : buildSettings.target === 'linux' ? t('linux') : buildSettings.target === 'macos' ? t('macos') : buildSettings.target === 'web' ? t('web') : 'Android')
const targetNote = computed(() => buildSettings.target === 'web' ? t('webExportNote') : buildSettings.target === 'android' ? t('androidExportNote') : t('hostTargetNote'))
const progressTitle = computed(() => t(buildProgress.phase === 'idle' ? 'buildIdle' : buildProgress.phase === 'validating' ? 'buildValidating' : buildProgress.phase === 'packing' ? 'buildPacking' : buildProgress.phase === 'exporting' ? 'buildExporting' : buildProgress.phase === 'complete' ? 'buildComplete' : 'buildFailed'))
const privacySummary = computed(() => telemetryPrivacySummary().map(key => t(key)))
const permissionText = computed({ get: () => buildSettings.platform.permissions.join(', '), set: value => { buildSettings.platform.permissions = [...new Set(value.split(',').map(item => item.trim()).filter(Boolean))].slice(0, 64) } })
const iconAsset = computed({ get: () => buildSettings.platform.iconAsset ?? '', set: value => { buildSettings.platform.iconAsset = value.trim() || null } })
const splashAsset = computed({ get: () => buildSettings.platform.splashAsset ?? '', set: value => { buildSettings.platform.splashAsset = value.trim() || null } })
const manifestAsset = computed({ get: () => buildSettings.platform.manifestAsset ?? '', set: value => { buildSettings.platform.manifestAsset = value.trim() || null } })
const includeRules = computed({ get: () => buildSettings.delivery.include.join(', '), set: value => { buildSettings.delivery.include = value.split(',').map(item => item.trim()).filter(Boolean).slice(0, 128) } })
const excludeRules = computed({ get: () => buildSettings.delivery.exclude.join(', '), set: value => { buildSettings.delivery.exclude = value.split(',').map(item => item.trim()).filter(Boolean).slice(0, 128) } })
const platformGuidance = computed(() => buildSettings.target === 'windows' ? t('windowsSigningGuide') : buildSettings.target === 'macos' ? t('macSigningGuide') : buildSettings.target === 'linux' ? t('linuxPackagingGuide') : buildSettings.target === 'android' ? t('androidSigningGuide') : t('webHostingGuide'))
function sceneName(uuid: string) { return sceneManager.scenes.find(scene => scene.uuid === uuid)?.name ?? uuid }
function move(index: number, direction: -1 | 1) { const target = index + direction; if (target < 0 || target >= buildSettings.sceneOrder.length) return; const [uuid] = buildSettings.sceneOrder.splice(index, 1); buildSettings.sceneOrder.splice(target, 0, uuid) }
function applyPreset(): void { buildSettings.platform.orientation = buildSettings.target === 'android' ? 'landscape' : 'auto'; buildSettings.packageIntoExecutable = buildSettings.target === 'windows' || buildSettings.target === 'linux'; buildSettings.delivery.deterministic = true; buildSettings.delivery.incremental = true; buildSettings.delivery.patchManifest = true }
async function runBuild(run: boolean) { const task = startTask(t('build'), { detail: `${buildSettings.target} · ${buildSettings.profile}`, progress: 0 }); try { for(const item of pluginBuildContributions.value)if(!pluginRuntime.invokeContribution(item.kind,item.id,item.pluginId))throw new Error(`${item.pluginName}: build contribution ${item.label} failed or was unloaded.`); const result = await buildGame(run); updateTask(task, { progress: 1 }); completeTask(task, result.outputPath) } catch (error) { failBuild(error); failTask(task, error) } }
onMounted(() => { synchronizeBuildScenes(sceneManager.scenes.map(scene => scene.uuid)); void detectExportCapabilities() })
watch(() => buildSettings.target, target => { buildSettings.presetName = 'custom'; if (target === 'web' || target === 'macos' || target === 'android') buildSettings.packageIntoExecutable = false })
watch(() => buildSettings.delivery.cacheMode, mode => { buildSettings.delivery.incremental = mode !== 'clean' })
watch(() => [buildSettings.outputDirectory, buildSettings.platform.signingIdentity, buildSettings.platform.notarizationProfile], persistBuildLocalSettings)
</script>

